"""Private storage for uploaded CVs.

The files live outside the source tree and outside any directory a web server
serves statically, so a candidate's CV can only be read through the protected
admin download endpoint. The database stores the generated storage name and
the original filename - never a filesystem path and never the file itself.

Security decisions in this module:

* The name on disk is generated by us (`uuid4().hex + ".pdf"`), so a malicious
  filename can never escape the directory or overwrite another applicant's CV.
* The extension, the declared MIME type and the `%PDF-` signature are all
  checked. The first two are easy to fake, which is exactly why the signature
  is checked too.
* The file is read in 1 MB chunks and aborted as soon as it passes the limit,
  so a 2 GB upload is rejected without filling the server's memory.
* A file is written to `<name>.part` and renamed only when complete. A crash
  therefore cannot leave a half-written CV that looks valid.

Local disk is enough for this assessment. In production the same functions
would write to S3 or another object store; the rest of the code would not
change because it only deals with the storage name.
"""

from __future__ import annotations

import logging
import os
from pathlib import Path
from typing import NamedTuple
from uuid import uuid4

from fastapi import UploadFile

from backend.schemas.application import CV_MAX_SIZE_BYTES
from backend.services.application_exceptions import CVFileMissingError, CVValidationError

logger = logging.getLogger(__name__)

# Default: <project root>/var/cvs (gitignored). Point CV_UPLOAD_DIR somewhere
# else - a mounted volume, for example - without touching the code.
_PROJECT_ROOT = Path(__file__).resolve().parents[3]
CV_DIRECTORY = Path(os.getenv("CV_UPLOAD_DIR", str(_PROJECT_ROOT / "var" / "cvs")))

# Every PDF starts with these five bytes ("%PDF-").
_PDF_MAGIC = b"%PDF-"
_CHUNK_SIZE = 1024 * 1024


class StoredCV(NamedTuple):
    """What the database needs to know about a CV that was just written."""

    storage_name: str
    original_filename: str
    content_type: str
    size_bytes: int


async def store_cv(upload: UploadFile) -> StoredCV:
    """Validate an uploaded file and save it under a generated name.

    Raises `CVValidationError` (a 422) when the file is not a PDF or is larger
    than 5 MB. The caller is responsible for deleting the file again if the
    database insert fails afterwards; `delete_cv` does that.
    """
    original_filename = _safe_original_filename(upload.filename)
    _check_extension(original_filename)
    _check_content_type(upload.content_type)

    CV_DIRECTORY.mkdir(parents=True, exist_ok=True)

    storage_name = f"{uuid4().hex}.pdf"
    destination = CV_DIRECTORY / storage_name
    temporary = destination.with_suffix(".part")

    total_bytes = 0

    try:
        with temporary.open("wb") as output:
            first_chunk = True

            while chunk := await upload.read(_CHUNK_SIZE):
                if first_chunk:
                    if not chunk.startswith(_PDF_MAGIC):
                        raise CVValidationError("The CV must be a real PDF file.")
                    first_chunk = False

                total_bytes += len(chunk)
                if total_bytes > CV_MAX_SIZE_BYTES:
                    raise CVValidationError("The CV must be 5 MB or smaller.")

                output.write(chunk)

        if total_bytes == 0:
            raise CVValidationError("The uploaded CV is empty.")

        # The file is only visible under its real name once it is complete.
        os.replace(temporary, destination)
    except Exception:
        temporary.unlink(missing_ok=True)
        raise
    finally:
        await upload.close()

    return StoredCV(
        storage_name=storage_name,
        original_filename=original_filename,
        content_type="application/pdf",
        size_bytes=total_bytes,
    )


def delete_cv(storage_name: str) -> None:
    """Remove a stored CV, for example when the database insert failed.

    Missing files are ignored on purpose: this runs on error paths and must not
    replace the original error with a second one.
    """
    try:
        (CV_DIRECTORY / Path(storage_name).name).unlink(missing_ok=True)
    except OSError:
        logger.warning("Could not delete stored CV %s", storage_name)


def resolve_cv_path(storage_name: str) -> Path:
    """Turn a storage name from the database into a safe absolute path.

    The containment check is a second line of defence. Storage names are
    generated by `store_cv`, so they never contain directories, but the check
    means a corrupted row still cannot be used to read `/etc/passwd`.
    """
    if not storage_name or storage_name != Path(storage_name).name:
        raise CVFileMissingError("The CV file is not available.")

    directory = CV_DIRECTORY.resolve()
    path = (directory / storage_name).resolve()

    if path.parent != directory or not path.is_file():
        raise CVFileMissingError("The CV file is not available.")

    return path


def _safe_original_filename(filename: str | None) -> str:
    """Keep a readable filename for the admin, without any path components."""
    # Windows clients may send backslashes; treat them as separators too.
    name = (filename or "").replace("\\", "/")
    name = Path(name).name
    # Control characters in a filename can break log lines and HTTP headers.
    name = "".join(character for character in name if character.isprintable()).strip()

    if name in {"", ".", ".."}:
        name = "cv.pdf"

    return name[:255]


def _check_extension(filename: str) -> None:
    if Path(filename).suffix.lower() != ".pdf":
        raise CVValidationError("The CV must be a PDF file.")


def _check_content_type(content_type: str | None) -> None:
    # Ignore parameters such as "; charset=binary".
    if (content_type or "").split(";")[0].strip().lower() != "application/pdf":
        raise CVValidationError("The CV must be a PDF file.")
